  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;Un b&#226;ton est un long bout de bois contenant plusieurs sorts. &#192; la diff&#233;rence des &lt;a class=&quot;pagelink&quot; href=&quot;Baguettes-Magiques.html&quot; title=&quot;Les baguettes magiques&quot;&gt;baguettes&lt;/a&gt;, qui peuvent contenir une grande vari&#233;t&#233; de sorts, chaque b&#226;ton appartient &#224; un mod&#232;le particulier, et contient certains sorts bien d&#233;finis. Un b&#226;ton nouvellement cr&#233;&#233; poss&#232;de 10 &lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Relatives-Aux-Objets-Magiques.html#CHARGESOBJETSMAGIQUES&quot; title=&quot;R&#232;gles relatives aux objets magiques&quot;&gt;charges&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Description.&lt;/b&gt; Un b&#226;ton fait g&#233;n&#233;ralement entre 1,20 m et 2,10 m de long, et fait entre 5 et 8 cm d’&#233;paisseur, pour un poids avoisinant les 2,5 kg. La plupart des b&#226;tons sont en bois, bien que certains, tr&#232;s rares, soient en ivoire, en m&#233;tal, ou m&#234;me en verre. Les b&#226;tons ont souvent une pierre pr&#233;cieuse ou un motif caract&#233;ristique dispos&#233; &#224; l’une de leurs extr&#233;mit&#233;s, dans le cas o&#249; ils ne sont pas ferr&#233;s (&#224; l’une ou l’autre extr&#233;mit&#233;). La plupart sont d&#233;cor&#233;s de runes et de divers symboles magiques. Ils peuvent ressembler &#224; une canne, &#224; un gourdin ou &#224; un b&#226;ton faisant office d’arme. Ils ont une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; de 7, 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Pointsdevie.html&quot; title=&quot;points de vie&quot;&gt;points de vie&lt;/a&gt;, une &lt;a class=&quot;pagelink&quot; href=&quot;Exploration#Solidite.html&quot; title=&quot;solidit&#233;&quot;&gt;solidit&#233;&lt;/a&gt; de 5 et le jet de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; pour les casser a un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de 24.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Activation.&lt;/b&gt; Tous les b&#226;tons sont des &lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Relatives-Aux-Objets-Magiques.html#OBJETSAPOTENTIELMAGIQUE&quot; title=&quot;R&#232;gles relatives aux objets magiques&quot;&gt;objets &#224; potentiel magique&lt;/a&gt;, ce qui signifie que leur activation est g&#233;n&#233;ralement une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; ne provoquant pas d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt;. Cependant, si le sort utilis&#233; a un &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Tempsdincantation.html&quot; title=&quot;temps d&amp;#39;incantation&quot;&gt;temps d’incantation&lt;/a&gt; sup&#233;rieur &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, le d&#233;lai d’activation du b&#226;ton est rallong&#233; d’autant. Pour activer un b&#226;ton, il faut le tenir &#224; une ou deux mains (ou &#224; tout ce qui sert de mains pour une cr&#233;ature non humano&#239;de) et le pointer dans la direction des cibles ou de la zone &#224; affecter.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Propri&#233;t&#233;s sp&#233;ciales.&lt;/b&gt; Lancer un d&#233;. Sur 01–30, un signe distinctif sugg&#233;rant sa fonction se trouve quelque part &#224; sa surface (dessin, inscription, etc.), et sur 31–100, il n’a aucune propri&#233;t&#233; sp&#233;ciale.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Utiliser les b&#226;tons.&lt;/b&gt; Les b&#226;tons profitent de la valeur de caract&#233;ristique primordiale et des dons de leur utilisateur pour d&#233;terminer le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; des &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre leurs effets. De plus, contrairement aux autres objets magiques, un utilisateur de magie lan&#231;ant un sort depuis un b&#226;ton utilise le plus &#233;lev&#233; entre son propre niveau de lanceur de sorts et celui de l’objet.&lt;br /&gt;&lt;br /&gt;Cela signifie qu’un b&#226;ton est d’autant plus puissant que son utilisateur l’est. Il est souvent plus difficile de r&#233;sister aux sorts d’un b&#226;ton que d’un autre objet magique, puisque la valeur du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; des &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; est calcul&#233;e d’apr&#232;s la valeur de caract&#233;ristique de leur utilisateur plut&#244;t que la valeur minimale exig&#233;e pour lancer le sort. Non seulement tous les aspects du sorts d&#233;pendant du niveau de lanceur de sorts (comme la port&#233;e, la dur&#233;e et ainsi de suite) seront souvent plus &#233;lev&#233;s, mais les sorts seront aussi plus difficiles &#224; dissiper et auront une meilleure chance de vaincre une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;RM&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;Les b&#226;tons contiennent un maximum de 10 &lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Relatives-Aux-Objets-Magiques.html#CHARGESOBJETSMAGIQUES&quot; title=&quot;R&#232;gles relatives aux objets magiques&quot;&gt;charges&lt;/a&gt;. Un sort lanc&#233; par son interm&#233;diaire utilise une ou plusieurs de ces &lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Relatives-Aux-Objets-Magiques.html#CHARGESOBJETSMAGIQUES&quot; title=&quot;R&#232;gles relatives aux objets magiques&quot;&gt;charges&lt;/a&gt;, et l’objet ne peut &#234;tre utilis&#233; une fois vide. Chaque matin, pendant qu’il pr&#233;pare ses sorts ou r&#233;cup&#232;re ses emplacements, un utilisateur de magie peut y transf&#233;rer une partie de son pouvoir, et ce faisant restaurer l’&#233;quivalent d’une &lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Relatives-Aux-Objets-Magiques.html#CHARGESOBJETSMAGIQUES&quot; title=&quot;R&#232;gles relatives aux objets magiques&quot;&gt;charge&lt;/a&gt;, et d’une seule, &#224; la condition qu’au moins un des sorts lanc&#233;s par le b&#226;ton soit sur sa liste et qu’il soit capable de le lancer. S’il choisit cette option, le personnage devra sacrifier un sort d’un niveau &#233;quivalent au plus haut niveau de sort lanc&#233; par le b&#226;ton. Par exemple, un &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; de niveau 9 poss&#233;dant un &lt;a class=&quot;pagelink&quot; href=&quot;B&#226;ton-De-Feu.html&quot; title=&quot;B&#226;ton de feu&quot;&gt;b&#226;ton de feu&lt;/a&gt; pourra y transf&#233;rer une &lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Relatives-Aux-Objets-Magiques.html#CHARGESOBJETSMAGIQUES&quot; title=&quot;R&#232;gles relatives aux objets magiques&quot;&gt;charge&lt;/a&gt; par jour en utilisant l’un de ses sorts du 4e niveau. Un seul b&#226;ton peut &#234;tre recharg&#233; de la sorte chaque jour.&lt;br /&gt;&lt;br /&gt;De plus, un b&#226;ton peut contenir des sorts de n’importe quel niveau, contrairement &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Baguettes-Magiques.html&quot; title=&quot;Les baguettes magiques&quot;&gt;baguette&lt;/a&gt;, laquelle est limit&#233;e aux sorts du 4e niveau ou moins. Le niveau de lanceur de sorts minimal pour un b&#226;ton est de 8.&lt;br /&gt;&lt;br /&gt;&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;
